<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileGenderAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileGenderAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileGenderAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getGender returns null on a freshly created holder.
     */
    public function testGenderNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileGenderAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isGenderAssigned());
        $this->assertNull($holder->getGender());
    }
}
class ImplWithUserProfileGenderAttributeHolderUnitTest
{
    use UserProfileGenderAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedGenderRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultGender();
    }
}
